class IncorrectLoginCredentials(Exception):
    """ Raises when response type from login is invalid. Credentials are wrong. """


class AuthenticationFailed(Exception):
    """ Raises when authentication to security API failed. """


class AsirVersionNotSupported(Exception):
    """ Raises when provided ASIR version is not supported by REST API. """


class PlanFileNotFound(Exception):
    """ Raises when provided ASIR plan file not exists """
    pass


class AsirOperationTimeout(Exception):
    """ Raises when operation on ASIR exceeds the time limit """
